{
  "items": [
    {
      "name": "Finsupp.le_weight",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} (w : σ → ℕ) {s : σ}, w s ≠ 0 → ∀ (f : σ →₀ ℕ), f s ≤ (Finsupp.weight w) f"
    },
    {
      "name": "Finsupp.le_weight_of_ne_zero'",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_4} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M]\n  [CanonicallyOrderedAdd M] (w : σ → M) {s : σ} {f : σ →₀ ℕ}, f s ≠ 0 → w s ≤ (Finsupp.weight w) f"
    },
    {
      "name": "MvPowerSeries.weightedOrder_le",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {d : σ →₀ ℕ},\n  (MvPowerSeries.coeff d) f ≠ 0 → MvPowerSeries.weightedOrder w f ≤ ↑((Finsupp.weight w) d)"
    },
    {
      "name": "HahnSeries.cardSupp_smul_le",
      "module_name": "Mathlib.RingTheory.HahnSeries.Cardinal",
      "kind": "theorem",
      "type": "∀ {Γ : Type u_1} {R : Type u_2} {S : Type u_3} [inst : PartialOrder Γ] [inst_1 : Zero R] (s : S) (x : HahnSeries Γ R)\n  [inst_2 : SMulZeroClass S R], (s • x).cardSupp ≤ x.cardSupp"
    },
    {
      "name": "MeasureTheory.norm_weightedSMul_le",
      "module_name": "Mathlib.MeasureTheory.Integral.Bochner.L1",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {F : Type u_3} [inst : NormedAddCommGroup F] [inst_1 : NormedSpace ℝ F] {m : MeasurableSpace α}\n  {μ : MeasureTheory.Measure α} (s : Set α), ‖MeasureTheory.weightedSMul μ s‖ ≤ μ.real s"
    }
  ]
}
